import abc


class Shape(abc.ABC):
    @abc.abstractmethod
    def area(self):
        pass


class Square(Shape):
    def __init__(self, side):
        self.side = side

    def area(self):
        return self.side ** 2


print(Square(3).area())
try:
    Shape()
except TypeError as e:
    print(type(e).__name__)

class Quacker(type):
    def __instancecheck__(cls, instance):
        return hasattr(instance, "quack")


class Quackable(metaclass=Quacker):
    pass


class Duck:
    def quack(self):
        return "quack"


class Seal:
    def quack(self):
        return "ow"


print(isinstance(Duck(), Quackable))
print(isinstance(Seal(), Quackable))
print(isinstance(42, Quackable))

