def add_repr(cls):
    def __repr__(self):
        return f"{type(self).__name__}({self.value})"

    cls.__repr__ = __repr__
    return cls


@add_repr
class Money:
    def __init__(self, value):
        self.value = value


print(repr(Money(7)))
print(type(Money).__name__)
